function redactStoredData(value,key=''){
  if(typeof value==='string'){
    if(localPersonFields.has(key.toLowerCase())&&value.trim()){const id=value.trim().toLowerCase();if(!localPeople.has(id))localPeople.set(id,`Person ${String(localPeople.size+1).padStart(2,'0')}`);return localPeople.get(id)}
    if(/^(?:email|phone|mobile|telephone|nationalid|passport|ssn|accountnumber|subscriberid|memberid|address|streetaddress|homeaddress|city|village|coordinates|latitude|longitude|gps|disabilitystatus|medicalcondition|healthstatus)$/i.test(key)&&value.trim())return '[REDACTED_FIELD]';
    return value.replace(/\b(?:sk-[A-Za-z0-9_-]{12,}|tvly-[A-Za-z0-9_-]{12,}|nvapi-[A-Za-z0-9_-]{12,}|AIza[A-Za-z0-9_-]{30,}|AKIA[A-Z0-9]{16}|gh[pousr]_[A-Za-z0-9]{20,})\b/g,'[REDACTED_SECRET]').replace(/\bBearer\s+[A-Za-z0-9._~+/-]{12,}=*/gi,'Bearer [REDACTED_SECRET]').replace(/\b(?:api[_ -]?key|access[_ -]?token|secret[_ -]?key)\s*[:=]\s*[^\s,;]{12,}/gi,'[REDACTED_SECRET]').replace(/\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/gi,'[REDACTED_EMAIL]').replace(/\b(?:phone|mobile|telephone|cell(?:ular)?(?:\s+phone)?)\s*[:=]\s*[^\r\n,;]{5,40}/gi,'[REDACTED_PHONE]').replace(/(?<!\d)(?:\+\d{1,3}[ .()-]?)?(?:\(?0?7\d\)?[ .-]?\d{3}[ .-]?\d{4}|\d{3}[ .-]\d{3}[ .-]\d{4})(?!\d)/g,'[REDACTED_PHONE]').replace(/\b(?:25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)(?:\.(?:25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)){3}\b/g,'[REDACTED_IP]').replace(/\b(?:national\s+id|government\s+id|passport(?:\s+(?:number|no))?|ssn|social\s+security(?:\s+number)?|resident\s+id|subscriber\s+(?:id|number)|customer\s+account\s+(?:id|number)|account\s+number|member\s+id|contract\s+number)\s*[:#=]?\s*[A-Z0-9-]{5,24}\b/gi,'[REDACTED_ID]').replace(/\b(?:gps\s+)?(?:coordinates?|lat(?:itude)?\s*[,/; ]\s*lon(?:gitude)?)\s*[:=]\s*-?\d{1,3}(?:\.\d+)?\s*[,;/ ]\s*-?\d{1,3}(?:\.\d+)?|\b(?:lat(?:itude)?)\s*[:=]\s*-?\d{1,3}(?:\.\d+)?\s*[,;/ ]\s*(?:lon(?:gitude)?|lng)\s*[:=]?\s*-?\d{1,3}(?:\.\d+)?/gi,'[REDACTED_COORDINATES]').replace(/\b(?:home\s+address|street\s+address|mailing\s+address|postal\s+address|residential\s+address|address|precise\s+location)\s*[:=]\s*[^\r\n;]{5,160}/gi,'[REDACTED_ADDRESS]').replace(/\b(?:city|village|town|residential\s+area|home\s+location|district)\s*[:=]\s*[^\r\n,;]{2,100}/gi,'[REDACTED_LOCATION]').replace(/\b(?:full\s+name|person\s+name|contact\s+name|employee\s+name|customer\s+name|first\s+name|last\s+name|reported\s+by|assigned\s+to|requester)\s*[:=]\s*[A-Z][\p{L}'’-]+(?:\s+[A-Z][\p{L}'’-]+){0,3}/giu,'[REDACTED_PERSON]').replace(/\b(?:disability\s+status|medical\s+condition|diagnosis|health\s+status)\s*[:=]\s*[^\r\n;]{2,120}/gi,'[REDACTED_SENSITIVE_DATA]');
  }
  if(Array.isArray(value))return value.map(item=>redactStoredData(item));
  if(value&&typeof value==='object')return Object.fromEntries(Object.entries(value).map(([childKey,child])=>[childKey,redactStoredData(child,childKey)]));
  return value;
}try{
  const saved=JSON.parse(localStorage.getItem('assurehub-demo')||'null');
  if(saved){
    if(Array.isArray(saved.apps))apps.splice(0,apps.length,...redactStoredData(saved.apps));
    if(Array.isArray(saved.scenarios))scenarios.splice(0,scenarios.length,...redactStoredData(saved.scenarios));
    if(Array.isArray(saved.runs))runs.splice(0,runs.length,...redactStoredData(saved.runs));
    if(Array.isArray(saved.findings))findings.splice(0,findings.length,...redactStoredData(saved.findings));
    if(Array.isArray(saved.automationRuns))automationRuns=redactStoredData(saved.automationRuns.filter(r=>r&&typeof r==='object'&&Array.isArray(r.scenarios)&&Array.isArray(r.gaps)&&r.scenarios.every(s=>s&&typeof s.title==='string'&&Array.isArray(s.requirementRefs))).slice(0,20));
    localStorage.setItem('assurehub-demo',JSON.stringify(redactStoredData({apps,scenarios,runs,findings,automationRuns})));
  }
}catch{}function saveDemoState(){try{localStorage.setItem('assurehub-demo',JSON.stringify(redactStoredData({apps,scenarios,runs,findings,automationRuns})))}catch{}}
function badge(status){const key=String(status).toLowerCase().replaceAll(' ','-');const cls=({passed:'pass',healthy:'ready',failed:'fail',critical:'critical',review:'review','at-risk':'warn',blocked:'blocked','in-progress':'in-progress','awaiting-evidence':'review',open:'open',running:'running',closed:'closed'})[key]||'neutral';return `<span class="badge ${cls}"><span class="status-bullet ${['pass','ready','closed'].includes(cls)?'green':['fail','critical','blocked'].includes(cls)?'red':['review','warn','in-progress'].includes(cls)?'yellow':cls==='running'?'gray':'gray'}"></span>${esc(status)}</span>`}
function logo(app){return `<span class="app-logo" style="background:${app.color}">${esc(app.initials)}</span>`}
function appRow(a){return `<tr data-app="${esc(a.name)}"><td><div class="app-cell">${logo(a)}<div><div class="app-name">${esc(a.name)}</div><div class="app-type">${esc(a.type)}</div></div></div></td><td>${esc(a.version)}</td><td>${esc(a.env)}</td><td><div class="owner-cell"><span class="mini-avatar">${esc(a.initials)}</span>${esc(a.owner)}</div></td><td><span class="coverage"><b>${a.coverage}%</b></span></td><td>${badge(a.status)}</td><td><button class="row-link" data-open-app="${esc(a.id)}">View details</button></td></tr>`}
